package com.secretvault.ai.dto;

import com.fasterxml.jackson.annotation.JsonInclude;
import java.util.Map;

/**
 * Server-validated action proposal generated by AI Copilot.
 * Requires human confirmation, policy validation, Step-Up verification, or Four-Eyes review.
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record AiActionProposal(
        String id,
        String type,
        String label,
        String description,
        String resourceType,
        String resourceId,
        String route,
        String risk,
        boolean requiresConfirmation,
        boolean requiresStepUp,
        boolean requiresFourEyes,
        Map<String, Object> payload
) {
    public static AiActionProposal navigate(
            String id,
            String label,
            String resourceType,
            String resourceId,
            String route
    ) {
        return new AiActionProposal(
                id,
                "NAVIGATE",
                label,
                "Navigate to " + resourceType.toLowerCase() + " page",
                resourceType,
                resourceId,
                route,
                "LOW",
                false,
                false,
                false,
                Map.of("route", route != null ? route : "/")
        );
    }

    public static AiActionProposal openInvitation(String invitationId) {
        return new AiActionProposal(
                "act_inv_" + invitationId,
                "NAVIGATE",
                "Open Invitation",
                "View and respond to pending workspace invitation",
                "INVITATION",
                invitationId,
                "/workspaces/invitations",
                "LOW",
                false,
                false,
                false,
                Map.of("invitationId", invitationId != null ? invitationId : "")
        );
    }

    public static AiActionProposal rotateSecret(
            String secretId,
            String secretKey,
            String environmentName,
            int consumerCount
    ) {
        return new AiActionProposal(
                "act_rot_" + secretId,
                "EXECUTE_ROTATION",
                "Rotate Credential: " + secretKey,
                "Trigger automated rollover with dual-version tolerance window for " + consumerCount + " known consumers.",
                "SECRET",
                secretId,
                "/rotation",
                "PROD".equalsIgnoreCase(environmentName) ? "HIGH" : "MEDIUM",
                true,
                "PROD".equalsIgnoreCase(environmentName),
                "PROD".equalsIgnoreCase(environmentName) && consumerCount > 5,
                Map.of(
                        "secretId", secretId != null ? secretId : "",
                        "secretKey", secretKey != null ? secretKey : "",
                        "environment", environmentName != null ? environmentName : "DEV"
                )
        );
    }

    public static AiActionProposal reconcileSync(
            String providerId,
            String providerType,
            String targetEnvironment
    ) {
        return new AiActionProposal(
                "act_sync_" + providerId,
                "RECONCILE_SYNC",
                "Reconcile Drift: " + providerType,
                "Reconcile authoritative hash across target cloud providers.",
                "PROVIDER",
                providerId,
                "/sync-center",
                "MEDIUM",
                true,
                false,
                false,
                Map.of(
                        "providerId", providerId != null ? providerId : "",
                        "providerType", providerType != null ? providerType : "",
                        "environment", targetEnvironment != null ? targetEnvironment : ""
                )
        );
    }
}
